args.TargetContent:
"The search is bounded by a default cutoff of $k = 12$ hops.  This
bound reflects the practical observation that attack chains longer
than twelve independently exploitable steps are not actionable
findings~\cite{sheyner2002}.  The cutoff is a configurable parameter;
setting it to zero removes the bound entirely.

\begin{algorithm}[t]
\caption{Attack-Path Enumeration}
\label{alg:reach}
\begin{algorithmic}[1]
\Require Influence graph $G$ (multigraph); entry set $S$;
         critical set $C$; path-length cutoff $k$
\Ensure Simple directed paths from $S$ to $C$,
        each annotated with per-hop authentication labels
\If{$S = \emptyset$ \textbf{ or } $C = \emptyset$}
  \State \Return gap record (not an empty path list)
\EndIf
\State $G' \gets$ simple directed projection of $G$
\ForAll{$s \in S$, $c \in C$ with $s \neq c$}
  \ForAll{node sequence $\pi \in
          \Call{AllSimplePaths}{G', s, c, k}$}
    \ForAll{consecutive pair $(u, v)$ in $\pi$}
      \State $e^* \gets \arg\max_e
             \bigl[a(e){=}\textsc{False},\;
             b(e),\; \mathrm{id}(e)\bigr]$
             over edges $(u,v)$ in $G$
    \EndFor
    \State record $\pi$ with hops annotated by $a(e^*)$ and $b(e^*)$
  \EndFor
\EndFor
\end{algorithmic}
\end{algorithm}"

